    if (v.signals && !v.signals.off) parts.push(LF('주간 신호: {0}{1}.', 'Weekly signal: {0}{1}.', sigText(v.signals.color), v.signals.color === 'bad' ? L(' — 충전 기안 차단, 24시간 안 반환·이관 제안', ' — top-up request blocked, propose refund or transfer within 24 hours') : v.signals.color === 'warn' ? L(' — 충전 보류, 1주 안 원인 확인', ' — top-up on hold, check the cause within one week') : ''));
